function filterObject(obj, predicate) {
  const result = {};
  for (const key in obj) {
    if (!Object.prototype.hasOwnProperty.call(obj, key)) continue;
    if (predicate(obj[key], key)) result[key] = obj[key];
  }
  return result;
}
